package com.vandorlabs.neoforge.ramp;
import com.mojang.serialization.MapCodec;
import com.vandorlabs.neoforge.mixin.NativeRampChunkStorageAccess;
import java.util.*;
import java.util.concurrent.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.level.chunk.storage.ChunkSerializer;
import net.minecraft.world.phys.AABB;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
/** Real disk preparation, partial world publication and recovery; not a geometry/generation substitute. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeRampJournalChecks {
 private static final BlockPos ROOT=new BlockPos(22900,90,22900),CHEST=ROOT.east(11),STONE=ROOT.east(12),UNRELATED=ROOT.south(3);private static Fixture rootBlock,proxyBlock;private static BlockEntityType<NativeRampEntity> rootType;private static BlockEntityType<NativeRampJournalPart> partType;private static ServerLevel world;private static ServerPlayer actor;private static NativeRampJournal.Operation operation;private static CountDownLatch gate;private static int phase,ticks,checks;private static CompletableFuture<Void> chunkWrite,flush;private static String mode;private static boolean newerWritten,injected;
 private static boolean enabled(){return System.getProperty("vandorlabs.transmitterPhase","").startsWith("ramp-journal-");}private static void need(boolean ok,String text){checks++;if(!ok)throw new AssertionError("Ramp journal: "+text);}
 private static final class Fixture extends BaseEntityBlock {final boolean proxy;Fixture(boolean proxy){super(BlockBehaviour.Properties.of().strength(1));this.proxy=proxy;}protected MapCodec<Fixture> codec(){return MapCodec.unit(this);}public BlockEntity newBlockEntity(BlockPos p,BlockState s){return proxy?new Proxy(p,s):new NativeRampEntity(rootType,p,s,false);}}
 private static final class Proxy extends NativeRampJournalPart {Proxy(BlockPos p,BlockState s){super(partType,p,s);}@Override public List<AABB> physicalBounds(){return getBlockState().getCollisionShape(getLevel(),getBlockPos()).toAabbs().stream().map(box->box.move(getBlockPos())).toList();}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{rootBlock=new Fixture(false);proxyBlock=new Fixture(true);h.register(ResourceLocation.parse("vandorlabs:ramp_journal_root"),rootBlock);h.register(ResourceLocation.parse("vandorlabs:ramp_journal_proxy"),proxyBlock);});e.register(Registries.BLOCK_ENTITY_TYPE,h->{rootType=BlockEntityType.Builder.<NativeRampEntity>of((p,s)->new NativeRampEntity(rootType,p,s,false),rootBlock).build(null);partType=BlockEntityType.Builder.<NativeRampJournalPart>of(Proxy::new,proxyBlock).build(null);h.register(ResourceLocation.parse("vandorlabs:ramp_journal_root"),rootType);h.register(ResourceLocation.parse("vandorlabs:ramp_journal_proxy"),partType);});}}
 private static NativeRampEntity owner(){return (NativeRampEntity)world.getBlockEntity(ROOT);}private static int diamonds(){var tile=world.getBlockEntity(CHEST);int count=0;if(tile instanceof net.minecraft.world.Container c)for(int i=0;i<c.getContainerSize();i++)if(c.getItem(i).is(Items.DIAMOND))count+=c.getItem(i).getCount();return count;}
 private static void noDrops(){need(world.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(ROOT).inflate(25)).stream().noneMatch(item->item.getItem().is(Items.DIAMOND)),"no duplicated/ejected inventory owner");}
 @SubscribeEvent public static void started(ServerStartedEvent e){if(!enabled())return;world=e.getServer().overworld();mode=System.getProperty("vandorlabs.transmitterPhase").substring("ramp-journal-".length());for(var p:List.of(ROOT,CHEST,STONE)){world.getChunkAt(p);world.setChunkForced(p.getX()>>4,p.getZ()>>4,true);}actor=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(new UUID(0,5701),"RampJournal"));actor.setPos(ROOT.getX()+.5,ROOT.getY(),ROOT.getZ()-2);actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);
  if(mode.equals("write")||mode.equals("crash")||mode.equals("iofail")||mode.equals("checkpoint-fail")){world.setBlock(ROOT,rootBlock.defaultBlockState(),18);world.setBlock(CHEST,Blocks.CHEST.defaultBlockState(),18);var chest=(ChestBlockEntity)world.getBlockEntity(CHEST);chest.setItem(0,new ItemStack(Items.DIAMOND,7));chest.getPersistentData().putString("OpaqueRampSource","private:one");world.setBlock(STONE,Blocks.DIAMOND_BLOCK.defaultBlockState(),18);world.setBlock(UNRELATED,Blocks.STONE.defaultBlockState(),18);world.getServer().saveEverything(true,true,true);gate=new CountDownLatch(1);NativeRampJournal.testFault=stage->{if(stage.equals("before-write")&&gate.getCount()>0)try{if(!gate.await(15,TimeUnit.SECONDS))throw new IllegalStateException("Fixture disk gate timeout");}catch(InterruptedException ex){Thread.currentThread().interrupt();throw new RuntimeException(ex);}};}phase=0;
 }
 @SubscribeEvent public static void tick(ServerTickEvent.Post e){if(world==null)return;if(++ticks>700)throw new AssertionError("Ramp journal timeout mode="+mode+" phase="+phase+" op="+(operation==null?"none":operation.phase()+"/"+operation.error()));try{step();}catch(Exception failure){throw new RuntimeException(failure);}}
 private static void step()throws Exception{
  if(mode.equals("read")||mode.equals("iofail-read")||mode.equals("recover")||mode.equals("checkpoint-recover")){if(phase==0){var loaded=NativeRampJournal.load(world);need(loaded!=NativeRampJournal.Status.REFUSED,"recovery directory load");if(loaded!=NativeRampJournal.Status.READY)return;operation=NativeRampJournal.atRoot(world,ROOT);if(mode.endsWith("read")){need(operation==null,"completed journal retired after checkpoint");need(diamonds()==7&&world.getBlockState(STONE).is(Blocks.DIAMOND_BLOCK),"saved one usable original owner");need(world.getBlockState(UNRELATED).is(Blocks.GOLD_BLOCK),"newer unrelated chunk snapshot survives reload");noDrops();finish(false);return;}need(operation!=null,"abrupt capture journal found");if(mode.equals("recover"))need(world.getBlockState(CHEST).is(proxyBlock)&&world.getBlockState(STONE).is(Blocks.DIAMOND_BLOCK),"actual cross-chunk partial-save layout chest="+world.getBlockState(CHEST)+" second="+world.getBlockState(STONE));else need((world.getBlockState(CHEST).is(Blocks.CHEST)||world.getBlockState(CHEST).is(proxyBlock))&&(world.getBlockState(STONE).is(Blocks.DIAMOND_BLOCK)||world.getBlockState(STONE).is(proxyBlock)),"checkpoint failure leaves a recognized before/proxy mixture");phase=1;}if(phase==1){var result=NativeRampJournal.recover(world,operation);need(result!=NativeRampJournal.Status.REFUSED,"loaded recovery "+operation.error());if(result!=NativeRampJournal.Status.DONE)return;need(diamonds()==7&&world.getBlockState(STONE).is(Blocks.DIAMOND_BLOCK),"partial-save recovery restores exactly one owner");noDrops();finish(false);}return;}
  switch(phase){case 0->{var denied=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(new UUID(0,5702),"RampDenied")){@Override public boolean mayUseItemAt(BlockPos p,Direction face,ItemStack item){return !p.equals(STONE)&&super.mayUseItemAt(p,face,item);}};denied.setPos(ROOT.getX()+.5,ROOT.getY(),ROOT.getZ()-2);denied.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);need(NativeRampJournal.prepare(owner(),denied,List.of(CHEST,STONE),proxyBlock.defaultBlockState(),false).status()==NativeRampJournal.Status.REFUSED,"all affected claims checked before journal admission");var noRamp=NativeRampReservations.prepareClose(world.getServer().getLevel(Level.NETHER),ROOT,com.vandorlabs.redstone.ChannelList.EMPTY,new AABB(ROOT).inflate(30),new NativeRampReservations.SweepQuery(){public NativeRampReservations.Status readiness(){throw new AssertionError("empty loaded index requested sweep");}public boolean intersects(AABB b){throw new AssertionError("empty loaded index traced geometry");}});need(noRamp.status()==NativeRampReservations.Status.READY,"empty loaded index proves clear without sweep");world.noSave=true;var disabled=NativeRampJournal.prepare(owner(),actor,List.of(CHEST,STONE),proxyBlock.defaultBlockState(),false);need(disabled.status()==NativeRampJournal.Status.PENDING,"disabled saving is pending");world.noSave=false;var start=NativeRampJournal.prepare(owner(),actor,List.of(CHEST,STONE),proxyBlock.defaultBlockState(),false);need(start.status()!=NativeRampJournal.Status.REFUSED,"preparation admitted "+start.error());operation=start.operation();if(operation==null)return;phase=1;}
   case 1->{need(NativeRampJournal.poll(world,operation)==NativeRampJournal.Status.PENDING,"real asynchronous pending preparation");need(diamonds()==7&&world.getBlockState(STONE).is(Blocks.DIAMOND_BLOCK),"pending disk work leaves sources usable and unchanged");need(NativeRampJournal.locked(world,CHEST),"source ownership held while preparing");gate.countDown();if(mode.equals("iofail"))NativeRampJournal.testFault=stage->{if(stage.equals("after-file-sync")&&!injected){injected=true;throw new java.io.UncheckedIOException(new java.io.IOException("fixture disk synchronization failure"));}};phase=2;}
   case 2->{var result=NativeRampJournal.poll(world,operation);if(mode.equals("iofail")){if(result!=NativeRampJournal.Status.REFUSED)return;need(injected&&diamonds()==7&&world.getBlockState(STONE).is(Blocks.DIAMOND_BLOCK),"real I/O failure preserves original ownership");installNewerWrite();phase=4;return;}need(result!=NativeRampJournal.Status.REFUSED,"durable preparation "+operation.error());if(operation.phase()!=NativeRampJournal.Phase.PREPARED)return;need(diamonds()==7,"durable prepare still leaves source owner");if(mode.equals("write")){owner().copiedChannelFooter(com.vandorlabs.redstone.ChannelList.of(13,17));actor.setPos(ROOT.getX()+100.5,ROOT.getY(),ROOT.getZ()-2);}need(NativeRampJournal.arm(world,operation,actor)==NativeRampJournal.Status.PENDING,"arm is separately durable");phase=3;}
   case 3->{var result=NativeRampJournal.poll(world,operation);need(result!=NativeRampJournal.Status.REFUSED,"arm completed "+operation.error());if(operation.phase()!=NativeRampJournal.Phase.ARMED)return;if(mode.equals("write"))NativeRampJournal.testFault=stage->{if(stage.equals("after-proxy")&&!injected){injected=true;throw new IllegalStateException("fixture caught partial publication");}};var applied=NativeRampJournal.apply(world,operation,actor);if(mode.equals("write")){need(applied==NativeRampJournal.Status.REFUSED&&injected,"caught publication exception reported");need(world.getBlockState(STONE).is(Blocks.DIAMOND_BLOCK),"caught partial publication leaves later source untouched");}else need(applied==NativeRampJournal.Status.READY,"real proxy publication "+operation.error());need(diamonds()==0&&world.getBlockState(CHEST).is(proxyBlock),"only journal owns captured inventory");noDrops();if(!mode.equals("write"))reservationChecks();if(mode.equals("crash")){world.noSave=true;var chunk=world.getChunkSource().getChunkNow(CHEST.getX()>>4,CHEST.getZ()>>4);chunkWrite=world.getChunkSource().chunkMap.write(new ChunkPos(CHEST),ChunkSerializer.write(world,chunk));phase=6;}else{if(mode.equals("checkpoint-fail"))NativeRampJournal.testFault=stage->{if(stage.equals("before-checkpoint-write")&&!injected){injected=true;try{var worker=((NativeRampChunkStorageAccess)(Object)world.getChunkSource().chunkMap).vandorlabs$rampWorker();var field=net.minecraft.world.level.chunk.storage.IOWorker.class.getDeclaredField("storage");field.setAccessible(true);((net.minecraft.world.level.chunk.storage.RegionFileStorage)field.get(worker)).close();}catch(Exception failure){throw new RuntimeException(failure);}}};else installNewerWrite();phase=4;}}
   case 4->{var result=NativeRampJournal.recover(world,operation);if(mode.equals("checkpoint-fail")){if(result!=NativeRampJournal.Status.REFUSED)return;need(injected&&diamonds()==7&&operation.error().contains("Closed"),"actual region I/O failure propagates and keeps before-image ownership "+operation.error());var realm=java.util.HexFormat.of().formatHex(world.dimension().location().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));var file=world.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("vandorlabs/ramp-journals").resolve(realm).resolve(operation.id()+".nbt");need(java.nio.file.Files.exists(file),"checkpoint failure cannot retire durable journal");noDrops();finish(true);return;}need(result!=NativeRampJournal.Status.REFUSED,"restore/checkpoint "+operation.error());if(result!=NativeRampJournal.Status.DONE)return;need(newerWritten&&diamonds()==7,"one restored owner and newer queued save");need(((ChestBlockEntity)world.getBlockEntity(CHEST)).getPersistentData().getString("OpaqueRampSource").equals("private:one"),"opaque source fields restored");need(!NativeRampJournal.locked(world,CHEST),"retirement releases only completed ownership");noDrops();finish(false);}
   case 6->{if(!chunkWrite.isDone())return;chunkWrite.join();flush=((NativeRampChunkStorageAccess)(Object)world.getChunkSource().chunkMap).vandorlabs$rampWorker().synchronize(true);phase=7;}
   case 7->{if(!flush.isDone())return;flush.join();need(world.getBlockState(CHEST).is(proxyBlock)&&world.getBlockState(STONE).is(proxyBlock),"memory has both proxies before abrupt stop");finish(true);}
  }
 }
 private static void reservationChecks(){var area=new AABB(ROOT).inflate(30);var channels=com.vandorlabs.redstone.ChannelList.EMPTY;var pending=NativeRampReservations.prepareClose(world,ROOT,channels,area,new NativeRampReservations.SweepQuery(){public NativeRampReservations.Status readiness(){return NativeRampReservations.Status.PENDING;}public boolean intersects(AABB b){throw new AssertionError("pending sweep inspected geometry");}});need(pending.status()==NativeRampReservations.Status.PENDING,"pending Canopy sweep is not READY/refused");var blocked=NativeRampReservations.prepareClose(world,ROOT,channels,area,new NativeRampReservations.SweepQuery(){public NativeRampReservations.Status readiness(){return NativeRampReservations.Status.READY;}public boolean intersects(AABB b){return b.intersects(new AABB(CHEST));}});need(blocked.status()==NativeRampReservations.Status.PENDING&&blocked.blockedCells().contains(CHEST)&&blocked.partnerRoots().contains(ROOT),"actual owned proxy physical collision blocks Canopy");var clear=NativeRampReservations.prepareClose(world,ROOT,channels,area,new NativeRampReservations.SweepQuery(){public NativeRampReservations.Status readiness(){return NativeRampReservations.Status.READY;}public boolean intersects(AABB b){return false;}});need(clear.status()==NativeRampReservations.Status.READY,"actual non-Moat physical proxies cleared by sweep");}
 private static void installNewerWrite(){NativeRampJournal.testFault=stage->{if(stage.equals("checkpoint-written")&&!newerWritten){newerWritten=true;world.setBlock(UNRELATED,Blocks.GOLD_BLOCK.defaultBlockState(),18);var chunk=world.getChunkSource().getChunkNow(ROOT.getX()>>4,ROOT.getZ()>>4);world.getChunkSource().chunkMap.write(new ChunkPos(ROOT),ChunkSerializer.write(world,chunk));}};}
 private static void finish(boolean abrupt){NativeRampJournal.testFault=null;System.out.println("[vandorlabs][ramp-journal] "+mode+" PASS checks="+checks+" abrupt="+abrupt);System.out.flush();var server=world.getServer();world=null;if(abrupt)Runtime.getRuntime().halt(0);else{server.saveEverything(true,true,true);server.halt(false);}}
}
